const Searchbox = props => {
  React.useEffect(() => {
    const submitButton = document.getElementsByClassName(
      'ais-SearchBox-submit'
    )[0]
    submitButton.setAttribute('tabindex', -1)
  }, [])
  return (
    <StyledSearchbox
      autoFocus
      submit={<Search width={20} />}
      reset={<Cross width={11} />}
      translations={{
        submitTitle: null,
        resetTitle: null,
        placeholder: null,
      }}
      {...props}
    />
  )
}

export default Searchbox

